SELECT m.*, CAST(m.mbmode24 AS INT) cls, m.deforestarea2124/10000.0 post2020_ha
FROM '/tmp/matched.parquet' m;
CREATE OR REPLACE TABLE msc AS SELECT ms.*, s.mb_class,s.annex1,s.in_scope FROM ms JOIN scope s ON ms.cls=s.cls;
-- flagged: cadaster with in-scope post2020 loss
CREATE OR REPLACE TABLE flagged AS
SELECT DISTINCT cod_imovel FROM msc WHERE in_scope AND post2020_ha>0;
SELECT count(*) AS n_flagged FROM flagged;
-- dominant class per flagged cadaster (max hectares over all matched fields, tie lower code)
CREATE OR REPLACE TABLE domcls AS
SELECT cod_imovel, cls AS dominant_mb FROM (
  SELECT cod_imovel, cls, sum(field_area_ha) ha,
   row_number() OVER (PARTITION BY cod_imovel ORDER BY sum(field_area_ha) DESC, cls ASC) rn
  FROM msc GROUP BY cod_imovel, cls
) WHERE rn=1;
COPY (SELECT * FROM domcls ORDER BY cod_imovel) TO '/tmp/domcls.csv' (HEADER,DELIMITER ',');
EOF
duckdb -init /tmp/init.sql < /tmp/flag.sql 2>&1 | grep -viE '^--|WARNING|axis|geometry|LATITUDE|current|Please|\*|^$'
echo "=== flagged dominant classes ==="; cat /tmp/domcls.csv
